import{_ as t,o as d,c as a,aF as r}from"./chunks/framework.DW71Y2Bc.js";const l=JSON.parse('{"title":"API","description":"API reference for the feathers-tasks building blocks","frontmatter":{"title":"API","description":"API reference for the feathers-tasks building blocks"},"headers":[],"relativePath":"packages/feathers-tasks/API.md","filePath":"packages/feathers-tasks/API.md"}'),o={name:"packages/feathers-tasks/API.md"};function s(c,e,i,n,h,p){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h1><p><code>feathers-tasks</code> is assembled from composable building blocks — there is no single <code>app.configure()</code> plugin. Each function below is imported from <code>@kalisio/feathers-tasks</code>.</p><h2 id="createqueue-name-redisoptions" tabindex="-1">createQueue (name, redisOptions) <a class="header-anchor" href="#createqueue-name-redisoptions" aria-label="Permalink to &quot;createQueue (name, redisOptions)&quot;">​</a></h2><p>Creates a BullMQ <code>Queue</code> connected to Redis and returns it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Queue name — must match the worker and queue-events.</td></tr><tr><td><code>redisOptions</code></td><td>object</td><td>yes</td><td>Redis connection options passed to BullMQ (<code>{ host, port, password, ... }</code>).</td></tr></tbody></table><h2 id="createworker-queuename-redisoptions-handlers-concurrency" tabindex="-1">createWorker (queueName, redisOptions, handlers?, concurrency?) <a class="header-anchor" href="#createworker-queuename-redisoptions-handlers-concurrency" aria-label="Permalink to &quot;createWorker (queueName, redisOptions, handlers?, concurrency?)&quot;">​</a></h2><p>Creates a BullMQ <code>Worker</code> that dispatches each job to the handler matching its type, and returns it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>queueName</code></td><td>string</td><td>yes</td><td>Queue to consume.</td></tr><tr><td><code>redisOptions</code></td><td>object</td><td>yes</td><td>Redis connection options.</td></tr><tr><td><code>handlers</code></td><td>object</td><td>no</td><td>Map of <code>taskType → async (job) =&gt; any</code>. Selected from <code>job.name</code>. Default: <code>{}</code>.</td></tr><tr><td><code>concurrency</code></td><td>number</td><td>no</td><td>Jobs processed in parallel by this worker. Default: <code>1</code>.</td></tr></tbody></table><blockquote><p>If no handler matches a job&#39;s type, the worker resolves it as a no-op (it does not throw).</p></blockquote><h2 id="setupqueueevents-queuename-redisoptions-app-persistenceservice" tabindex="-1">setupQueueEvents (queueName, redisOptions, app, persistenceService) <a class="header-anchor" href="#setupqueueevents-queuename-redisoptions-app-persistenceservice" aria-label="Permalink to &quot;setupQueueEvents (queueName, redisOptions, app, persistenceService)&quot;">​</a></h2><p>Subscribes to the queue lifecycle events (<code>active</code>, <code>progress</code>, <code>completed</code>, <code>failed</code>) and patches the persistence record accordingly. Returns the <code>QueueEvents</code> instance.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>queueName</code></td><td>string</td><td>yes</td><td>Queue to observe.</td></tr><tr><td><code>redisOptions</code></td><td>object</td><td>yes</td><td>Redis connection options.</td></tr><tr><td><code>app</code></td><td>Feathers app</td><td>yes</td><td>Used to resolve the persistence service.</td></tr><tr><td><code>persistenceService</code></td><td>string</td><td>yes</td><td>Name of the Feathers service holding task history.</td></tr></tbody></table><h2 id="setupdashboard-app-queue-basepath" tabindex="-1">setupDashboard (app, queue, basePath) <a class="header-anchor" href="#setupdashboard-app-queue-basepath" aria-label="Permalink to &quot;setupDashboard (app, queue, basePath)&quot;">​</a></h2><p>Mounts the <a href="https://github.com/felixmosh/bull-board" target="_blank" rel="noreferrer">Bull Board</a> UI as Express middleware on the underlying app.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>app</code></td><td>Feathers app</td><td>yes</td><td>Must be an Express-powered Feathers app (<code>@feathersjs/express</code>).</td></tr><tr><td><code>queue</code></td><td>Queue</td><td>yes</td><td>The BullMQ queue to expose.</td></tr><tr><td><code>basePath</code></td><td>string</td><td>yes</td><td>URL path where the dashboard is served, e.g. <code>/admin/tasks</code>.</td></tr></tbody></table><h2 id="new-taskservice-queue-persistenceservice" tabindex="-1">new TaskService ({ queue, persistenceService }) <a class="header-anchor" href="#new-taskservice-queue-persistenceservice" aria-label="Permalink to &quot;new TaskService ({ queue, persistenceService })&quot;">​</a></h2><p>Feathers service constructor.</p><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>queue</code></td><td>Queue</td><td>yes</td><td>A BullMQ queue (from <code>createQueue</code>).</td></tr><tr><td><code>persistenceService</code></td><td>string</td><td>yes</td><td>Name of the Feathers service used to store task history.</td></tr></tbody></table><p>Register it with <code>app.use(&#39;tasks&#39;, new TaskService({ ... }))</code>. Its methods follow.</p><h2 id="taskservice" tabindex="-1">TaskService <a class="header-anchor" href="#taskservice" aria-label="Permalink to &quot;TaskService&quot;">​</a></h2><h3 id="create-data-params" tabindex="-1">create (data, params) <a class="header-anchor" href="#create-data-params" aria-label="Permalink to &quot;create (data, params)&quot;">​</a></h3><p>Submits a new task to the BullMQ queue and creates a record in the persistence service.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>data.type</code></td><td>string</td><td>yes</td><td>Job type — matched against a key in <code>handlers</code>.</td></tr><tr><td><code>data.payload</code></td><td>object</td><td>no</td><td>Arbitrary data forwarded to the handler as <code>job.data</code>.</td></tr><tr><td><code>data.options</code></td><td>object</td><td>no</td><td>BullMQ <a href="https://api.docs.bullmq.io/types/v5.JobsOptions.html" target="_blank" rel="noreferrer">JobsOptions</a> (delay, attempts, priority, etc.).</td></tr></tbody></table><p>Returns the persisted task record:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BullMQ job id.</td></tr><tr><td><code>type</code></td><td>Job type.</td></tr><tr><td><code>payload</code></td><td>Data passed to the handler.</td></tr><tr><td><code>status</code></td><td><code>&#39;waiting&#39;</code> at creation time.</td></tr><tr><td><code>createdAt</code></td><td>ISO timestamp.</td></tr></tbody></table><h3 id="find-params" tabindex="-1">find (params) <a class="header-anchor" href="#find-params" aria-label="Permalink to &quot;find (params)&quot;">​</a></h3><p>Delegates to the persistence service. Accepts the same <code>params.query</code> as the underlying adapter.</p><p>Returns a list (or paginated result) of task records.</p><h3 id="get-id-params" tabindex="-1">get (id, params) <a class="header-anchor" href="#get-id-params" aria-label="Permalink to &quot;get (id, params)&quot;">​</a></h3><p>Retrieves a single task record from the persistence service by BullMQ job <code>id</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BullMQ job id (string).</td></tr></tbody></table><p>Throws <code>NotFound</code> if no record matches.</p><h3 id="patch-id-data-params" tabindex="-1">patch (id, data, params) <a class="header-anchor" href="#patch-id-data-params" aria-label="Permalink to &quot;patch (id, data, params)&quot;">​</a></h3><p>Updates fields on a task record in the persistence service. Primarily used internally by the <code>QueueEvents</code> listener to reflect status changes.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BullMQ job id.</td></tr><tr><td><code>data</code></td><td>Fields to merge into the record (e.g. <code>{ status, completedAt, result }</code>).</td></tr></tbody></table><h3 id="remove-id-params" tabindex="-1">remove (id, params) <a class="header-anchor" href="#remove-id-params" aria-label="Permalink to &quot;remove (id, params)&quot;">​</a></h3><p>Cancels the BullMQ job (if still pending) and removes the record from the persistence service.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BullMQ job id.</td></tr></tbody></table><p>Throws <code>NotFound</code> if no persistence record matches. Does not throw if the job is no longer in the queue (already completed/failed).</p>',39)])])}const b=t(o,[["render",s]]);export{l as __pageData,b as default};
